20	public class AuditSettingChanged {
21	    public void audit(@Val Sheet sheet, @Val SettingsInput input, @Val Settings settings,
22	            HttpServletRequest request, Audit audit) {
23	        String head = "SETTING_CHANGED sheet=" + sheet.id() + " by=" + Audit.user(request);
24	        input.datedValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
25	        if (input.policyDateChanged()) {
26	            audit.record(head + " key=policy-date value=" + (input.policyDate() == null ? "" : input.policyDate()));
27	        }
28	        if (input.periodNumberingFromChanged()) {
29	            audit.record(head + " key=period-numbering-from value="
30	                    + (input.periodNumberingFrom() == null ? "" : input.periodNumberingFrom()));
31	        }
32	        input.gradeTermsValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
33	        if (input.capValue() != null) audit.record(line(head, Settings.CAP, input.capValue(), input));
34	        if (input.proofThresholdValue() != null) {
35	            audit.record(line(head, Settings.PROOF_THRESHOLD, input.proofThresholdValue(), input));
36	        }
37	        if (input.noteThresholdValue() != null) {
38	            audit.record(line(head, Settings.NOTE_THRESHOLD, input.noteThresholdValue(), input));
39	        }
40	        input.perms().forEach((action, roles) -> audit.record(head + " key=" + Settings.permKey(action) + " value=" + roles));
41	        if (input.graceDaysChanged()) {
42	            audit.record(head + " key=grace-days value=" + (input.graceDays() == null ? "" : input.graceDays()));
43	        }
44	        if (input.entryDateChanged()) {
45	            audit.record(head + " key=entry-date value=" + (input.entryDate() == null ? "" : input.entryDate()));
46	        }
47	        input.gradeGraceValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
48	        input.gradeProofThresholdValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
49	        if (input.potChanged()) {
50	            audit.record(head + " key=pot value=" + (input.pot() == null ? "" : input.pot().toPlainString()));
51	        }
52	        if (input.fiscalStartMonthChanged()) {
53	            audit.record(head + " key=fiscal-start-month value=" + input.fiscalStartMonth());
54	        }
55	        if (input.alertThresholdChanged()) {
56	            audit.record(head + " key=" + Settings.ALERT_THRESHOLD + " value="
57	                    + (input.alertThreshold() == null ? "" : input.alertThreshold().toPlainString()));
58	        }
59	        if (input.roundingValue() != null) audit.record(line(head, Settings.ROUNDING, input.roundingValue(), input));
60	        if (input.reviewThresholdValue() != null) {
61	            audit.record(line(head, Settings.REVIEW_THRESHOLD, input.reviewThresholdValue(), input));
62	        }
63	        if (input.escalateAfterChanged()) {
64	            audit.record(head + " key=" + Settings.ESCALATE_AFTER + " value="
65	                    + (input.escalateAfter() == null ? "" : input.escalateAfter()));
66	        }
67	        if (input.reviewSlaChanged()) {
68	            audit.record(head + " key=" + Settings.REVIEW_SLA + " value="
69	                    + (input.reviewSla() == null ? "" : input.reviewSla()));
70	        }
71	        if (input.proofKindsChanged()) {
72	            audit.record(head + " key=" + Settings.PROOF_KINDS + " value="
73	                    + (input.proofKinds() == null ? "" : input.proofKinds()));
74	        }
75	        if (input.parentChanged()) {
76	            audit.record(head + " key=parent value=" + (input.parent() == null ? "" : input.parent()));
77	        }
78	    }
79	
80	    private static String line(String head, String key, String value, SettingsInput input) {
81	        LocalDate from = input.from().get(key);
82	        return head + " key=" + key + " value=" + value + (from == null ? "" : " from=" + from);
83	    }
84	}
